import { omitEmpty } from '@splendidlabz/utils'
import { get, writable } from 'svelte/store'

export const tabs = writable([])
const { update } = tabs

export function getTabs() {
  return get(tabs)
}

export function getTab(id) {
  return get(tabs).find(tab => tab.id === id)
}

export function addTab({ id, state = {}, nodes = {}, options = {} }) {
  update(tabs => {
    const tab = { id, state, options, nodes }
    return [...tabs, tab]
  })
}

export function updateTab({ id, state = {}, nodes = {}, options = {} }) {
  update(tabs => {
    const index = tabs.findIndex(t => t.id === id)
    const tab = tabs[index]

    omitEmpty(nodes, { shallow: true })

    tab.state = { ...tab.state, ...omitEmpty(state) }
    tab.nodes = { ...tab.nodes, ...nodes }
    tab.options = { ...tab.options, ...omitEmpty(options) }

    return tabs.with(index, tab)
  })
}

export function initTab({ id, state = {}, nodes = {}, options = {} }) {
  const tab = getTab(id)

  state = omitEmpty(state)
  options = omitEmpty(options)

  // Update the tab with given state, nodes, and options
  if (!tab) {
    // Add the tab with given state, nodes, and options
    addTab({ id, state, nodes, options })
  } else {
    // Defensive check for length
    // If length doesn't exist, component has not initialized tablist or tabpanel yet. Once it does, we can check whether the length is consistent.
    // if (tab.state.length && tab.state.length !== state.length) {
    //   throw new Error(
    //     'Number of tabs must be the same as the number of tabpanels. Please check.',
    //   )
    // }
    updateTab({ id: tab.id, state, nodes, options })
  }

  return getTab(id)
}
